content:
Below is an idiomatic Pulumi TypeScript `ComponentResource` that wraps:

- an **S3 bucket** with versioning, encryption, and blocked public access
- an **RDS PostgreSQL instance** with deletion protection
- an **IAM role for Kubernetes service accounts** using **OIDC trust**

It supports **dev/prod** via **stack config**.

---

## 1) Component: `AppInfra.ts`

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface AppInfraArgs {
    environment: "dev" | "prod";

    // Networking for RDS
    vpcId: pulumi.Input<string>;
    privateSubnetIds: pulumi.Input<pulumi.Input<string>[]>;
    dbAllowedSecurityGroupIds: pulumi.Input<pulumi.Input<string>[]>;

    // App / DB
    appName: string;
    dbName: string;
    dbUsername: string;
    dbPassword: pulumi.Input<string>;

    // IRSA / OIDC inputs from your EKS cluster
    oidcProviderArn: pulumi.Input<string>;
    oidcIssuerUrl: pulumi.Input<string>; // e.g. https://oidc.eks.us-east-1.amazonaws.com/id/XXXX
    k8sNamespace: string;
    serviceAccountName: string;

    // Optional overrides
    bucketName?: pulumi.Input<string>;
    tags?: Record<string, pulumi.Input<string>>;
}

export class AppInfra extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.BucketV2;
    public readonly db: aws.rds.Instance;
    public readonly serviceAccountRole: aws.iam.Role;
    public readonly dbSecurityGroup: aws.ec2.SecurityGroup;
    public readonly connectionString: pulumi.Output<string>;

    constructor(name: string, args: AppInfraArgs, opts?: pulumi.ComponentResourceOptions) {
        super("custom:infra:AppInfra", name, {}, opts);

        const tags = {
            app: args.appName,
            env: args.environment,
            ...args.tags,
        };

        //
        // S3 bucket
        //
        this.bucket = new aws.s3.BucketV2(`${name}-assets`, {
            bucket: args.bucketName,
            tags,
        }, { parent: this });

        new aws.s3.BucketVersioningV2(`${name}-bucket-versioning`, {
            bucket: this.bucket.id,
            versioningConfiguration: {
                status: "Enabled",
            },
        }, { parent: this.bucket });

        new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-bucket-sse`, {
            bucket: this.bucket.id,
            rules: [{
                applyServerSideEncryptionByDefault: {
                    sseAlgorithm: "AES256",
                },
            }],
        }, { parent: this.bucket });

        new aws.s3.BucketPublicAccessBlock(`${name}-bucket-pab`, {
            bucket: this.bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, { parent: this.bucket });

        //
        // RDS security group
        //
        this.dbSecurityGroup = new aws.ec2.SecurityGroup(`${name}-db-sg`, {
            vpcId: args.vpcId,
            description: `RDS security group for ${name}`,
            ingress: args.dbAllowedSecurityGroupIds.apply(ids =>
                ids.map((sgId) => ({
                    protocol: "tcp",
                    fromPort: 5432,
                    toPort: 5432,
                    securityGroups: [sgId],
                    description: "PostgreSQL from application SG",
                }))
            ),
            egress: [{
                protocol: "-1",
                fromPort: 0,
                toPort: 0,
                cidrBlocks: ["0.0.0.0/0"],
                description: "Allow all outbound",
            }],
            tags,
        }, { parent: this });

        const dbSubnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnets`, {
            subnetIds: args.privateSubnetIds,
            tags,
        }, { parent: this });

        const isProd = args.environment === "prod";

        //
        // RDS PostgreSQL
        //
        this.db = new aws.rds.Instance(`${name}-postgres`, {
            engine: "postgres",
            engineVersion: "15.7",
            instanceClass: isProd ? "db.t3.medium" : "db.t3.micro",

            allocatedStorage: isProd ? 50 : 20,
            maxAllocatedStorage: isProd ? 200 : 100,
            storageType: "gp3",
            storageEncrypted: true,

            dbSubnetGroupName: dbSubnetGroup.name,
            vpcSecurityGroupIds: [this.dbSecurityGroup.id],

            dbName: args.dbName,
            username: args.dbUsername,
            password: args.dbPassword,

            multiAz: isProd,
            publiclyAccessible: false,
            deletionProtection: true,
            backupRetentionPeriod: isProd ? 14 : 7,

            skipFinalSnapshot: false,
            finalSnapshotIdentifier: `${name}-${args.environment}-final-snapshot`,

            autoMinorVersionUpgrade: true,
            applyImmediately: true,

            tags,
        }, { parent: this });

        //
        // IAM role for Kubernetes service account (IRSA)
        //
        const oidcIssuerHost = pulumi.output(args.oidcIssuerUrl).apply(url =>
            url.replace("https://", "")
        );

        const assumeRolePolicy = pulumi.all([
            args.oidcProviderArn,
            oidcIssuerHost,
        ]).apply(([providerArn, issuerHost]) =>
            JSON.stringify({
                Version: "2012-10-17",
                Statement: [{
                    Effect: "Allow",
                    Principal: {
                        Federated: providerArn,
                    },
                    Action: "sts:AssumeRoleWithWebIdentity",
                    Condition: {
                        StringEquals: {
                            [`${issuerHost}:sub`]: `system:serviceaccount:${args.k8sNamespace}:${args.serviceAccountName}`,
                            [`${issuerHost}:aud`]: "sts.amazonaws.com",
                        },
                    },
                }],
            })
        );

        this.serviceAccountRole = new aws.iam.Role(`${name}-sa-role`, {
            assumeRolePolicy,
            tags,
        }, { parent: this });

        // Least-privilege bucket access for the app
        const appPolicyDoc = pulumi.all([this.bucket.arn]).apply(([bucketArn]) =>
            JSON.stringify({
                Version: "2012-10-17",
                Statement: [
                    {
                        Sid: "ListBucket",
                        Effect: "Allow",
                        Action: ["s3:ListBucket"],
                        Resource: [bucketArn],
                    },
                    {
                        Sid: "ReadWriteObjects",
                        Effect: "Allow",
                        Action: [
                            "s3:GetObject",
                            "s3:PutObject",
                            "s3:DeleteObject",
                        ],
                        Resource: [`${bucketArn}/*`],
                    },
                ],
            })
        );

        new aws.iam.RolePolicy(`${name}-sa-policy`, {
            role: this.serviceAccountRole.id,
            policy: appPolicyDoc,
        }, { parent: this.serviceAccountRole });

        //
        // Secret connection string output
        //
        this.connectionString = pulumi.secret(
            pulumi.interpolate`postgresql://${args.dbUsername}:${args.dbPassword}@${this.db.address}:${this.db.port}/${args.dbName}`
        );

        this.registerOutputs({
            bucketName: this.bucket.bucket,
            bucketArn: this.bucket.arn,
            dbAddress: this.db.address,
            dbPort: this.db.port,
            dbName: this.db.dbName,
            serviceAccountRoleArn: this.serviceAccountRole.arn,
            connectionString: this.connectionString,
        });
    }
}
```

