## 2) Stack entrypoint: `index.ts`

This reads values from stack config and creates the component.

```ts
import * as pulumi from "@pulumi/pulumi";
import { AppInfra } from "./AppInfra";

const config = new pulumi.Config();

const environment = pulumi.getStack() as "dev" | "prod";

const appName = config.get("appName") || "webapp";

// These should come from existing VPC/EKS stack outputs or config
const vpcId = config.require("vpcId");
const privateSubnetIds = config.requireObject<string[]>("privateSubnetIds");
const dbAllowedSecurityGroupIds = config.requireObject<string[]>("dbAllowedSecurityGroupIds");

// IRSA / OIDC
const oidcProviderArn = config.require("oidcProviderArn");
const oidcIssuerUrl = config.require("oidcIssuerUrl");
const k8sNamespace = config.get("k8sNamespace") || "default";
const serviceAccountName = config.get("serviceAccountName") || "webapp";

// DB config
const dbName = config.get("dbName") || "appdb";
const dbUsername = config.get("dbUsername") || "appuser";
const dbPassword = config.requireSecret("dbPassword");

const infra = new AppInfra(appName, {
    environment,
    appName,
    vpcId,
    privateSubnetIds,
    dbAllowedSecurityGroupIds,

    dbName,
    dbUsername,
    dbPassword,

    oidcProviderArn,
    oidcIssuerUrl,
    k8sNamespace,
    serviceAccountName,

    tags: {
        managedBy: "pulumi",
    },
});

export const bucketName = infra.bucket.bucket;
export const bucketArn = infra.bucket.arn;
export const dbEndpoint = infra.db.address;
export const dbPort = infra.db.port;
export const serviceAccountRoleArn = infra.serviceAccountRole.arn;
export const connectionString = infra.connectionString;
```

